const RUSH_QUESTIONS = [{"id": "r51243408", "genre": "溶液", "year": "2021本", "statement": "ヘキサンが水にほとんど溶けないのは、ヘキサン分子の極性が小さいためである。", "answer": true, "explanation": "水は極性分子、ヘキサンは極性の小さい分子なので、互いになじまず溶けにくい。"}, {"id": "r2e181439", "genre": "化学基礎：原子の構造・モル", "year": "2021本", "statement": "ナフタレンが溶解したヘキサン溶液では、ナフタレン分子とヘキサン分子の間に分子間力がはたらいている。", "answer": true, "explanation": "無極性分子どうしでも、ファンデルワールス力などの分子間力がはたらいている。"}, {"id": "r4a3a42e2", "genre": "化学基礎：原子の構造・モル", "year": "2021本", "statement": "液体では、液体の分子間にはたらく分子間力が小さいほど、その沸点は高くなる。", "answer": false, "explanation": "「高くなる」が誤り。分子間力が大きいほど分子を引き離すのにエネルギーが必要なので、沸点は高くなる（分子間力が小さいほど沸点は低い）。"}, {"id": "rf8fa293c", "genre": "反応速度", "year": "2021本", "statement": "塩素と水素の混合気体に強い光（紫外線）を照射すると、爆発的に反応して塩化水素が生成する。", "answer": true, "explanation": "光によって塩素分子が原子に分かれ、連鎖的に反応が進むため爆発的に HCl が生成する。"}, {"id": "re0a1e0f0", "genre": "熱化学", "year": "2021本", "statement": "植物は光合成で糖類を生成する。二酸化炭素と水からグルコースと酸素が生成する反応は、発熱反応である。", "answer": false, "explanation": "「発熱反応」が誤り。光合成は光エネルギーを吸収して進む吸熱反応（ΔH＞0）である（グルコースの燃焼の逆反応）。"}, {"id": "ra39a4978", "genre": "反応速度", "year": "2021本", "statement": "酸化チタン(Ⅳ)は、光（紫外線）を照射すると、有機物などを分解する触媒として作用する。", "answer": true, "explanation": "酸化チタン(Ⅳ) TiO₂ は光触媒として、光を受けると有機物などを分解するはたらきをする。"}, {"id": "r19dcfac7", "genre": "状態変化", "year": "2021本", "statement": "水の三重点よりも低温かつ低圧の状態に保たれている氷は、温度を保ったまま減圧すると、水蒸気に昇華する。", "answer": true, "explanation": "三重点より低温では、減圧すると昇華圧曲線を横切り、固体から直接気体になる。"}, {"id": "ra9158f0c", "genre": "状態変化", "year": "2021本", "statement": "水の三重点よりも低温かつ低圧の状態に保たれている氷は、温度を保ったまま加圧すると、水蒸気に昇華する。", "answer": false, "explanation": "加圧すると気体から遠ざかる（固体のまま）ので昇華しない。正しくは減圧すると昇華する。"}, {"id": "r5877c377", "genre": "状態変化", "year": "2021本", "statement": "水の三重点よりも低温かつ低圧の状態に保たれている氷は、圧力を保ったまま加熱すると、水蒸気に昇華する。", "answer": true, "explanation": "三重点より低い圧力では液体の領域を通らないので、加熱すると固体から直接気体に昇華する。"}, {"id": "r89e02a8e", "genre": "状態変化", "year": "2021本", "statement": "水の三重点よりも低温かつ低圧の状態に保たれている氷は、圧力を保ったまま冷却すると、水蒸気に昇華する。", "answer": false, "explanation": "冷却しても固体のままで昇華しない。正しくは圧力を保ったまま加熱すると昇華する。"}, {"id": "ree967d70", "genre": "電池・電気分解", "year": "2021本", "statement": "塩化ナトリウムの溶融塩電解（融解塩電解）では、陰極に鉄、陽極に黒鉛を用いることができる。", "answer": true, "explanation": "陽極は塩素と反応しにくい黒鉛を使う。陰極は Na⁺ が還元されるだけなので鉄でもよい。"}, {"id": "rbba39548", "genre": "電池・電気分解", "year": "2021本", "statement": "塩化ナトリウムの溶融塩電解では、ナトリウムの単体が陰極で生成し、気体の塩素が陽極で発生する。", "answer": true, "explanation": "陰極 Na⁺ ＋ e⁻ → Na、陽極 2Cl⁻ → Cl₂ ＋ 2e⁻。"}, {"id": "r1c519822", "genre": "電池・電気分解", "year": "2021本", "statement": "塩化ナトリウムの溶融塩電解では、ナトリウムの単体が1mol生成するとき、気体の塩素が1mol発生する。", "answer": false, "explanation": "「1mol」が誤り。電子1molで Na は1mol、Cl₂ は0.5mol（2Cl⁻ → Cl₂ ＋ 2e⁻）なので、塩素は0.5mol。"}, {"id": "r8dab03a2", "genre": "電池・電気分解", "year": "2021本", "statement": "塩化ナトリウム水溶液を電気分解しても、ナトリウムの単体は得られない。", "answer": true, "explanation": "水溶液では Na⁺ より水が還元されやすく、陰極では H₂ が発生する。そのため Na は溶融塩電解でつくる。"}, {"id": "rf269af18", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "酢酸 CH₃COOH は、二重結合をもち、非共有電子対を4組もつ分子である。", "answer": true, "explanation": "C=O の二重結合をもち、2個のO原子がそれぞれ非共有電子対を2組ずつもつので計4組。"}, {"id": "r5be1dc26", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "ジエチルエーテル C₂H₅OC₂H₅ は、二重結合をもち、非共有電子対を4組もつ分子である。", "answer": false, "explanation": "ジエチルエーテルは単結合だけからなり、非共有電子対はO原子の2組だけ。"}, {"id": "r40f98cf1", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "エテン（エチレン）CH₂=CH₂ は、二重結合をもち、非共有電子対を4組もつ分子である。", "answer": false, "explanation": "C=C の二重結合はもつが、C原子とH原子だけからなるので非共有電子対は0組。"}, {"id": "rbdf1c873", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "塩化ビニル CH₂=CHCl は、二重結合をもち、非共有電子対を4組もつ分子である。", "answer": false, "explanation": "C=C の二重結合はもつが、非共有電子対はCl原子の3組だけ。"}, {"id": "raf199262", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "1,2-エタンジオール（エチレングリコール）HOCH₂CH₂OH は、二重結合をもち、非共有電子対を4組もつ分子である。", "answer": false, "explanation": "非共有電子対は2個のO原子に2組ずつで計4組だが、二重結合をもたない（単結合のみ）。"}, {"id": "rdc3007ed", "genre": "溶液", "year": "2021追", "statement": "界面活性剤の分子が一定濃度以上で多数集合してできるミセルのようなコロイド粒子を、会合コロイドという。", "answer": true, "explanation": "多数の分子が集合してコロイド粒子になったものが会合コロイド（ミセルコロイド）。"}, {"id": "r8277a34a", "genre": "溶液", "year": "2021追", "statement": "界面活性剤の分子が一定濃度以上で多数集合してできるミセルのようなコロイド粒子を、分子コロイドという。", "answer": false, "explanation": "分子コロイドは、デンプンやタンパク質のように1個の分子がコロイド粒子の大きさをもつもの。ミセルは会合コロイド。"}, {"id": "raa6bf66b", "genre": "溶液", "year": "2021追", "statement": "8.2×10⁻³ mol/L 以上でミセルをつくる界面活性剤 C₁₂H₂₅−OSO₃⁻Na⁺ の 1.0×10⁻¹ mol/L 水溶液は、チンダル現象を示す。", "answer": true, "explanation": "濃度がミセル形成濃度を超えているのでコロイド粒子（ミセル）が存在し、光を散乱してチンダル現象を示す。"}, {"id": "r520cdb38", "genre": "溶液", "year": "2021追", "statement": "8.2×10⁻³ mol/L 以上でミセルをつくる界面活性剤 C₁₂H₂₅−OSO₃⁻Na⁺ の 1.0×10⁻¹ mol/L 水溶液は、チンダル現象を示さない。", "answer": false, "explanation": "1.0×10⁻¹ mol/L はミセル形成濃度より高く、ミセル（コロイド粒子）が光を散乱するのでチンダル現象を示す。"}, {"id": "r1d57f5eb", "genre": "溶液", "year": "2021追", "statement": "界面活性剤 C₁₂H₂₅−OSO₃⁻Na⁺ がつくるミセルは、電気泳動を行うと陽極側に移動する。", "answer": true, "explanation": "ミセルの表面には −OSO₃⁻ が並んでおり負に帯電しているので、陽極側へ移動する。"}, {"id": "rde20f205", "genre": "溶液", "year": "2021追", "statement": "界面活性剤 C₁₂H₂₅−OSO₃⁻Na⁺ がつくるミセルは、電気泳動を行うと陰極側に移動する。", "answer": false, "explanation": "ミセルの表面は −OSO₃⁻ で負に帯電しているので、陰極ではなく陽極側へ移動する。"}, {"id": "r591f7945", "genre": "電池・電気分解", "year": "2021追", "statement": "食塩水中で鉄を亜鉛と導線でつなぐと、鉄はイオン化されにくくなる。", "answer": true, "explanation": "イオン化傾向の大きい亜鉛が先に酸化されて溶け出すので、鉄の酸化（腐食）が防がれる。"}, {"id": "rda9d278a", "genre": "電池・電気分解", "year": "2021追", "statement": "食塩水中で鉄をスズと導線でつなぐと、鉄はイオン化されにくくなる。", "answer": false, "explanation": "スズは鉄よりイオン化傾向が小さいので、鉄のほうが負極となって酸化され、かえってイオン化されやすくなる。"}, {"id": "r847530f1", "genre": "電池・電気分解", "year": "2021追", "statement": "食塩水に亜鉛と鉄を浸し、鉄を外部電源の負極に、亜鉛を正極につなぐと、鉄はイオン化されにくくなる。", "answer": true, "explanation": "負極につながれた鉄には電子が送り込まれ、鉄の酸化（Fe → Fe²⁺）が起こりにくくなる。"}, {"id": "r720b3cf6", "genre": "電池・電気分解", "year": "2021追", "statement": "食塩水にスズと鉄を浸し、鉄を外部電源の正極に、スズを負極につなぐと、鉄はイオン化されにくくなる。", "answer": false, "explanation": "正極につながれた鉄からは電子が引き抜かれるので、鉄は酸化されてイオン化されやすくなる。"}, {"id": "rab80f24f", "genre": "化学平衡", "year": "2021追", "statement": "同じ物質量の NH₃ と NH₄Cl を溶かした混合水溶液に少量の塩酸を加えると、H⁺ が NH₃ と反応して NH₄⁺ となるので、pH はあまり変化しない。", "answer": true, "explanation": "加えたH⁺は多量にあるNH₃に受け取られてNH₄⁺になるので、[H⁺]がほとんど増えない（緩衝作用）。"}, {"id": "r057cb50a", "genre": "化学平衡", "year": "2021追", "statement": "同じ物質量の NH₃ と NH₄Cl を溶かした混合水溶液に少量の塩酸を加えると、H⁺ が OH⁻ と反応して H₂O となるので、pH はあまり変化しない。", "answer": false, "explanation": "この溶液中のOH⁻はわずかで、加えたH⁺を受け取るのは多量にあるNH₃（NH₃ + H⁺ → NH₄⁺）。"}, {"id": "r42677c8a", "genre": "化学平衡", "year": "2021追", "statement": "同じ物質量の NH₃ と NH₄Cl を溶かした混合水溶液に少量の NaOH 水溶液を加えると、OH⁻ が NH₄⁺ と反応して NH₃ と H₂O を生成するので、pH はあまり変化しない。", "answer": true, "explanation": "加えたOH⁻は多量にあるNH₄⁺と反応して（NH₄⁺ + OH⁻ → NH₃ + H₂O）消費されるので、pHはあまり変化しない。"}, {"id": "r3497dca7", "genre": "化学平衡", "year": "2021追", "statement": "同じ物質量の NH₃ と NH₄Cl を溶かした混合水溶液に少量の NaOH 水溶液を加えると、OH⁻ が NH₃ と反応して NH₄⁺ を生成するので、pH はあまり変化しない。", "answer": false, "explanation": "OH⁻と反応するのはNH₃ではなくNH₄⁺で、NH₃とH₂Oが生成する。"}, {"id": "r19728cee", "genre": "反応速度", "year": "2021追", "statement": "N₂ + 3H₂ → 2NH₃ の反応の活性化エネルギー（触媒なしで234 kJ）は、N≡N の結合エネルギー（946 kJ/mol）よりはるかに小さいので、この反応は気体状態で N₂ → 2N、H₂ → 2H の反応段階を経ていないことがわかる。", "answer": true, "explanation": "N₂やH₂を原子にばらばらにするには活性化エネルギーよりはるかに大きなエネルギーが必要なので、その段階を経ずに反応していると考えられる。"}, {"id": "rdb8db398", "genre": "反応速度", "year": "2021追", "statement": "N₂ + 3H₂ → 2NH₃（ΔH = −92 kJ）の反応では、触媒のあるときもないときも、逆反応の活性化エネルギーは正反応よりも大きい。", "answer": true, "explanation": "発熱反応（ΔH＜0）では、逆反応の活性化エネルギー＝正反応の活性化エネルギー＋|ΔH| となり、正反応より大きい。"}, {"id": "r8f7ee019", "genre": "反応速度", "year": "2021追", "statement": "N₂ + 3H₂ → 2NH₃ の反応エンタルピー（ΔH）の大きさは、触媒の有無にかかわらず変わらない。", "answer": true, "explanation": "触媒は活性化エネルギーを小さくするが、反応物と生成物のエネルギー差（ΔH）は変えない。"}, {"id": "re1fbecfa", "genre": "化学基礎：原子の構造・モル", "year": "2021追", "statement": "第4周期の遷移金属元素の原子がもつ最外殻電子数は、1または2である。", "answer": true, "explanation": "遷移元素では内側のd軌道（M殻）に電子が入っていくため、最外殻電子数は1または2（Cr・Cuは1）。"}, {"id": "r2d1610d2", "genre": "電池・電気分解", "year": "2021追", "statement": "リチウムイオン電池とリチウム電池は、ともに一次電池である。", "answer": false, "explanation": "リチウム電池は一次電池だが、リチウムイオン電池は充電できる二次電池。"}, {"id": "refadc047", "genre": "化学基礎：酸化還元", "year": "2021追", "statement": "SO₂ の水溶液をヨウ素溶液（ヨウ素ヨウ化カリウム水溶液）に加えると無色透明になることから、SO₂ の水溶液が還元作用をもつことがわかる。", "answer": true, "explanation": "SO₂ が I₂ を I⁻ に還元する（SO₂ + I₂ + 2H₂O → H₂SO₄ + 2HI）ので、ヨウ素の褐色が消える。"}, {"id": "r343da873", "genre": "化学基礎：酸化還元", "year": "2021追", "statement": "SO₂ の水溶液をアルカリ性のフェノールフタレイン水溶液に加えると無色透明になることから、SO₂ の水溶液が還元作用をもつことがわかる。", "answer": false, "explanation": "赤色が消えるのはSO₂水溶液が酸性で塩基を中和したためで、還元作用を示すものではない。"}, {"id": "r969b28d1", "genre": "化学基礎：酸化還元", "year": "2021追", "statement": "SO₂ の水溶液を硫酸鉄(Ⅱ)水溶液に加えると無色透明になることから、SO₂ の水溶液が還元作用をもつことがわかる。", "answer": false, "explanation": "Fe²⁺ 自身が還元剤なので、SO₂ の還元作用は確かめられない（無色透明にもならない）。"}, {"id": "r01489af7", "genre": "化学基礎：酸化還元", "year": "2021追", "statement": "SO₂ の水溶液を硫化水素水に加えると無色透明になることから、SO₂ の水溶液が還元作用をもつことがわかる。", "answer": false, "explanation": "H₂S との反応（SO₂ + 2H₂S → 3S + 2H₂O）では SO₂ は酸化剤としてはたらき、硫黄が析出して白濁する。"}, {"id": "r58ab1bba", "genre": "溶液", "year": "2021追", "statement": "水溶性のタンパク質が溶解したコロイド溶液に多量の電解質を加えると、水和している水分子が奪われ、コロイド粒子どうしが凝集して沈殿する。", "answer": true, "explanation": "親水コロイドに多量の電解質を加えると水和水が奪われて沈殿する（塩析）。"}, {"id": "rf2509f2e", "genre": "化学平衡", "year": "2021追", "statement": "コハク酸（2価の弱酸 H₂A）の水溶液を NaOH 水溶液で滴定するとき、NaOH 水溶液を加え始める時点では、コハク酸は主に H₂A の形で存在する。", "answer": true, "explanation": "弱酸なので電離度は小さく、塩基を加える前はほとんどが電離していない H₂A のまま存在する。"}, {"id": "r49d7ee0d", "genre": "化学平衡", "year": "2021追", "statement": "コハク酸（2価の弱酸 H₂A）の水溶液を NaOH 水溶液で滴定するとき、NaOH 水溶液を加え始める時点では、コハク酸は主に HA⁻ の形で存在する。", "answer": false, "explanation": "コハク酸は弱酸で電離度が小さいので、滴定開始時は主に H₂A の形で存在する。"}, {"id": "rbf875175", "genre": "化学平衡", "year": "2021追", "statement": "コハク酸（H₂A）の水溶液に、中和点を越えて NaOH 水溶液を過剰に加えた水溶液中では、コハク酸は主に A²⁻ の形で存在する。", "answer": true, "explanation": "中和点を過ぎて強塩基性になると、2個のカルボキシ基がともに中和され、主に A²⁻ となる。"}, {"id": "rf5e755c2", "genre": "化学平衡", "year": "2021追", "statement": "コハク酸（H₂A）の水溶液に、中和点を越えて NaOH 水溶液を過剰に加えた水溶液中では、コハク酸は主に HA⁻ の形で存在する。", "answer": false, "explanation": "中和点を過ぎて NaOH が過剰な強塩基性では、2段階目まで中和されて主に A²⁻ となる。"}, {"id": "r980e4018", "genre": "化学基礎：酸塩基", "year": "2021追", "statement": "コハク酸を含む試料をNaOH水溶液で中和滴定してコハク酸の量を求めるとき、試料中に NaHCO₃ や Na₂CO₃ が残っていると、求めたコハク酸の質量は正しい値よりも小さくなる。", "answer": true, "explanation": "残った炭酸塩（塩基）がコハク酸の一部を中和してしまうので、滴定に要する NaOH 水溶液が少なくなり、小さく求まる。"}, {"id": "r7aaf78fb", "genre": "化学基礎：酸塩基", "year": "2021追", "statement": "コハク酸を含む固体をNaOH水溶液で中和滴定してコハク酸の量を求めるとき、固体に塩化水素が残っていると、求めたコハク酸の質量は正しい値よりも小さくなる。", "answer": false, "explanation": "残った塩化水素（酸）もNaOHと反応するので、滴定に要するNaOH水溶液が多くなり、求めた質量は大きくなる。"}, {"id": "r2b88062d", "genre": "化学基礎：酸塩基", "year": "2021追", "statement": "コハク酸を含む固体を水に溶かしてNaOH水溶液で中和滴定するとき、溶かす水の量を多くすると、求めたコハク酸の質量は正しい値よりも小さくなる。", "answer": false, "explanation": "水で薄めても酸の物質量は変わらないので、中和に必要なNaOHの量も変わらず、求めた質量は変わらない。"}, {"id": "r594c4c2f", "genre": "化学基礎：酸塩基", "year": "2021追", "statement": "中和滴定で、実際に用いたNaOH水溶液の濃度が 1.00 mol/L よりも低いことに気づかずに 1.00 mol/L として計算すると、求めた酸の質量は正しい値よりも小さくなる。", "answer": false, "explanation": "濃度が低いと中和に要する体積が多くなり、それを1.00 mol/Lとして計算するので、求めた質量は大きくなる。"}, {"id": "r0a3dbe5c", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "アルミニウム Al の原子は、L殻に電子を3個もつ。", "answer": false, "explanation": "Al の電子配置は K2・L8・M3。3個もつのは最外殻の M殻で、L殻は8個。"}, {"id": "rd2abec49", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "ホウ素 B の原子は、L殻に電子を3個もつ。", "answer": true, "explanation": "B（原子番号5）の電子配置は K2・L3。"}, {"id": "rc552f712", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "リチウム Li の原子は、L殻に電子を3個もつ。", "answer": false, "explanation": "Li（原子番号3）の電子配置は K2・L1 で、L殻の電子は1個。"}, {"id": "r779346ab", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "マグネシウム Mg の原子は、L殻に電子を3個もつ。", "answer": false, "explanation": "Mg（原子番号12）の電子配置は K2・L8・M2 で、L殻の電子は8個。"}, {"id": "r340f56e6", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "窒素 N の原子は、L殻に電子を3個もつ。", "answer": false, "explanation": "N（原子番号7）の電子配置は K2・L5 で、L殻の電子は5個。"}, {"id": "rfe67533f", "genre": "固体", "year": "2022本", "statement": "ガラスは一定の融点を示さない。", "answer": true, "explanation": "ガラスは粒子の配列に規則性がない非晶質（アモルファス）なので、一定の融点を示さず、加熱するとしだいにやわらかくなる。"}, {"id": "r520f1ba4", "genre": "固体", "year": "2022本", "statement": "アモルファス金属やアモルファス合金は、高温で融解させた金属を急速に冷却してつくられる。", "answer": true, "explanation": "急冷すると原子が規則正しく並ぶ時間がなく、非晶質の金属・合金になる。"}, {"id": "re79bd831", "genre": "固体", "year": "2022本", "statement": "非晶質の二酸化ケイ素は、光ファイバーに利用される。", "answer": true, "explanation": "非晶質の SiO₂（石英ガラス）は透明度が高く、光ファイバーに用いられる。"}, {"id": "rccad389d", "genre": "固体", "year": "2022本", "statement": "ポリエチレンは、非晶質の部分（非結晶部分・無定形部分）の割合が増えるほどかたくなる。", "answer": false, "explanation": "「かたくなる」が誤り。結晶部分が多いほどかたく、非晶質部分の割合が増えるほどやわらかくなる。"}, {"id": "r3c7b5fda", "genre": "熱化学", "year": "2022本", "statement": "炭化水素が酸素の中で完全燃焼するときは、発熱の場合も吸熱の場合もある。", "answer": false, "explanation": "燃焼は常に発熱反応（ΔH＜0）である。"}, {"id": "r15bab83b", "genre": "熱化学", "year": "2022本", "statement": "強酸の希薄水溶液に強塩基の希薄水溶液を加えて中和するときは、発熱の場合も吸熱の場合もある。", "answer": false, "explanation": "中和反応（H⁺ ＋ OH⁻ → H₂O）は常に発熱（ΔH＜0）である。"}, {"id": "r18ee468e", "genre": "熱化学", "year": "2022本", "statement": "電解質が多量の水に溶解するときは、発熱の場合も吸熱の場合もある。", "answer": true, "explanation": "溶解エンタルピーは物質によって負（例：NaOH、発熱）にも正（例：NH₄NO₃、吸熱）にもなる。"}, {"id": "r99c97ce1", "genre": "熱化学", "year": "2022本", "statement": "常圧で純物質の液体が凝固して固体になるときは、発熱の場合も吸熱の場合もある。", "answer": false, "explanation": "凝固は常に発熱（ΔH＜0）である（融解は吸熱）。"}, {"id": "rcf7c3bfe", "genre": "電池・電気分解", "year": "2022本", "statement": "リン酸型燃料電池では、負極に水素、正極に酸素を供給する。", "answer": true, "explanation": "負極で H₂ が酸化され（H₂ → 2H⁺ ＋ 2e⁻）、正極で O₂ が還元される。"}, {"id": "r8bc94a44", "genre": "電池・電気分解", "year": "2022本", "statement": "リン酸型燃料電池では、水は正極で生成し、正極側から未反応の酸素とともに排出される。", "answer": true, "explanation": "正極で O₂ ＋ 4H⁺ ＋ 4e⁻ → 2H₂O の反応が起こるので、水は正極側から出てくる。"}, {"id": "ra8ab9f26", "genre": "電池・電気分解", "year": "2022本", "statement": "リン酸型燃料電池では、水は負極で生成し、負極側から未反応の水素とともに排出される。", "answer": false, "explanation": "水が生成するのは正極（O₂ ＋ 4H⁺ ＋ 4e⁻ → 2H₂O）。負極側から排出されるのは未反応の H₂ だけ。"}, {"id": "ra364d26d", "genre": "化学基礎：酸塩基", "year": "2022本", "statement": "AlK(SO₄)₂・12H₂O の水溶液と NaCl の水溶液は、フェノールフタレイン溶液を加えても区別できない。", "answer": true, "explanation": "ミョウバン水溶液は弱い酸性、NaCl 水溶液は中性で、どちらもフェノールフタレインは無色のままなので区別できない。"}, {"id": "r4aecadb4", "genre": "電池・電気分解", "year": "2022本", "statement": "白金電極で電気分解すると、NaCl 水溶液では陽極で塩素が、AlK(SO₄)₂・12H₂O 水溶液では陽極で酸素が発生するので、両者を区別できる。", "answer": true, "explanation": "Cl⁻ は酸化されて Cl₂ になるが、SO₄²⁻ は酸化されにくく水が酸化されて O₂ が発生する（陰極はどちらも H₂）。"}, {"id": "re96b37d6", "genre": "化学基礎：酸塩基", "year": "2022本", "statement": "CO₂ を水に溶かすと、水溶液は酸性を示す。", "answer": true, "explanation": "CO₂ は水と反応して炭酸 H₂CO₃ を生じ、弱い酸性を示す。"}, {"id": "r389c386c", "genre": "化学基礎：酸塩基", "year": "2022本", "statement": "Na₂CO₃ を水に溶かすと、水溶液は酸性を示す。", "answer": false, "explanation": "「酸性」が誤り。Na₂CO₃ は強塩基と弱酸からなる塩で、CO₃²⁻ が加水分解して塩基性を示す。"}, {"id": "r8e29ea46", "genre": "化学基礎：酸塩基", "year": "2022本", "statement": "NH₄Cl を水に溶かすと、水溶液は酸性を示す。", "answer": true, "explanation": "NH₄Cl は強酸と弱塩基からなる塩で、NH₄⁺ が加水分解して酸性を示す。"}, {"id": "ra5ab1e0c", "genre": "溶液", "year": "2022本", "statement": "NaHCO₃ の水への溶解度は、NH₄Cl より大きい。", "answer": false, "explanation": "「大きい」が誤り。NaHCO₃ は NH₄Cl より溶解度が小さいので、アンモニアソーダ法では NaHCO₃ が沈殿する。"}, {"id": "rdce9a2c1", "genre": "化学基礎：酸塩基", "year": "2022本", "statement": "アンモニアソーダ法で、NaCl 飽和水溶液に NH₃ を吸収させたあとに CO₂ を通じるのは、CO₂ を溶かしやすくするためである。", "answer": true, "explanation": "NH₃ で塩基性にしておくと、酸性の気体である CO₂ が中和されて多く溶け込む。"}, {"id": "rcfd82d53", "genre": "化学基礎：原子の構造・モル", "year": "2022本", "statement": "ブロモベンゼンの沸点は、ベンゼンの沸点より高い。", "answer": true, "explanation": "ブロモベンゼンは分子量が大きく極性もあるため、分子間力が大きく沸点が高い。"}, {"id": "r82f0e61c", "genre": "化学基礎：原子の構造・モル", "year": "2022追", "statement": "シアン化水素 HCN は三重結合をもつ分子である。", "answer": true, "explanation": "HCN は H−C≡N で、C と N の間が三重結合である。"}, {"id": "re03d7107", "genre": "化学基礎：原子の構造・モル", "year": "2022追", "statement": "フッ素 F₂ は三重結合をもつ分子である。", "answer": false, "explanation": "F₂ は F−F の単結合だけからなる。三重結合をもつのはシアン化水素 HCN である。"}, {"id": "r4bb830da", "genre": "化学基礎：原子の構造・モル", "year": "2022追", "statement": "アンモニア NH₃ は三重結合をもつ分子である。", "answer": false, "explanation": "NH₃ は N−H の単結合3本と非共有電子対1組からなり、三重結合はもたない。"}, {"id": "r2c7903e4", "genre": "化学基礎：原子の構造・モル", "year": "2022追", "statement": "シクロヘキセン C₆H₁₀ は三重結合をもつ分子である。", "answer": false, "explanation": "シクロヘキセンは環の中に C=C 二重結合を1つもつ分子で、三重結合はもたない。"}, {"id": "re2edd48e", "genre": "状態変化", "year": "2022追", "statement": "密閉容器に液体を入れて放置し、容器内の圧力が一定になった状態では、単位時間に液面から蒸発する分子の数と凝縮する分子の数が等しい。", "answer": true, "explanation": "圧力が一定になったのは気液平衡に達したためで、蒸発する分子数と凝縮する分子数が等しくなっている。"}, {"id": "r768654f4", "genre": "状態変化", "year": "2022追", "statement": "液体が沸騰しているときは、液体の表面だけでなく内部からも蒸発が起こっている。", "answer": true, "explanation": "沸騰は、蒸気圧が外圧に等しくなり、液体の内部からも気泡として蒸発が起こる現象である。"}, {"id": "r31db8a1a", "genre": "状態変化", "year": "2022追", "statement": "沸騰させて空気を追い出したシクロヘキサンの容器にゴム栓をして冷却すると、容器内の圧力が大気圧よりも低くなるため、シクロヘキサンは 81 ℃（大気圧下の沸点）よりも低い温度で再び沸騰する。", "answer": true, "explanation": "容器内はシクロヘキサンの蒸気だけになり、冷却で圧力が大気圧より下がる。外圧が低いと、蒸気圧が外圧に等しくなる温度（沸点）も低くなる。"}, {"id": "rd6f07cc5", "genre": "反応速度", "year": "2022追", "statement": "亜鉛が希塩酸に溶けて水素を発生する反応では、希塩酸の濃度が高いほうが反応速度が大きくなる。", "answer": true, "explanation": "反応物の濃度が高いほど粒子の衝突回数が増え、反応速度は大きくなる。"}, {"id": "r421ead50", "genre": "反応速度", "year": "2022追", "statement": "水素とヨウ素からヨウ化水素が生成する反応では、温度が高いほうが反応速度が大きくなる。", "answer": true, "explanation": "温度が高いほど活性化エネルギー以上のエネルギーをもつ分子の割合が増え、反応速度は大きくなる。"}, {"id": "rcd7ac87d", "genre": "反応速度", "year": "2022追", "statement": "石灰石に希塩酸を加えて二酸化炭素を発生させる反応では、石灰石の粒を砕いて小さくし、表面積を大きくすると反応速度が大きくなる。", "answer": true, "explanation": "固体が関わる反応では、表面積が大きいほど反応できる粒子が増え、反応速度が大きくなる。"}, {"id": "r347f5f16", "genre": "反応速度", "year": "2022追", "statement": "過酸化水素の分解反応では、過酸化水素水に触媒として酸化マンガン(Ⅳ)を少量加えると、活性化エネルギーが大きくなるので反応速度が大きくなる。", "answer": false, "explanation": "「活性化エネルギーが大きくなる」が誤り。正しくは、触媒は活性化エネルギーを小さくするので反応速度が大きくなる。"}, {"id": "r34965d0e", "genre": "化学平衡", "year": "2022追", "statement": "2NO₂ ⇄ N₂O₄ の平衡状態で温度を上げると、平衡は左向き（NO₂ が増える向き）に移動する。", "answer": true, "explanation": "正反応（N₂O₄ の生成）は発熱反応なので、温度を上げると吸熱方向の左向きに平衡が移動する。"}, {"id": "r9aea68c8", "genre": "化学平衡", "year": "2022追", "statement": "2NO₂ ⇄ N₂O₄ の平衡状態で温度を上げると、平衡は右向き（N₂O₄ が増える向き）に移動する。", "answer": false, "explanation": "「右向き」が誤り。正反応は発熱反応なので、温度を上げると平衡は吸熱方向の左向きに移動する。"}, {"id": "rf3f7baa7", "genre": "熱化学", "year": "2022追", "statement": "NO₂ から N₂O₄ が生成する反応（2NO₂ → N₂O₄）は発熱反応であり、ΔH < 0 である。", "answer": true, "explanation": "温度を上げると NO₂ が増える（平衡が左に移動する）ことから、正反応は発熱反応（ΔH < 0）とわかる。"}, {"id": "r41fbdb74", "genre": "熱化学", "year": "2022追", "statement": "NO₂ から N₂O₄ が生成する反応（2NO₂ → N₂O₄）は吸熱反応であり、ΔH > 0 である。", "answer": false, "explanation": "「吸熱反応」が誤り。正しくは発熱反応（ΔH < 0）で、温度を上げると平衡は左向きに移動する。"}, {"id": "rba7f4b23", "genre": "熱化学", "year": "2022追", "statement": "2NO₂ → N₂O₄ の反応エンタルピーは、NO₂ の生成エンタルピーと正反応の活性化エネルギーがわかれば計算で求められる。", "answer": false, "explanation": "N₂O₄ の生成エンタルピーか逆反応の活性化エネルギーが足りず求められない。活性化エネルギーを使うなら正反応と逆反応の両方が必要。"}, {"id": "rde2c31ef", "genre": "熱化学", "year": "2022追", "statement": "2NO₂ → N₂O₄ の反応エンタルピーは、N₂O₄ の生成エンタルピーと逆反応の活性化エネルギーがわかれば計算で求められる。", "answer": false, "explanation": "NO₂ の生成エンタルピーか正反応の活性化エネルギーが足りず求められない。"}, {"id": "r32a35606", "genre": "熱化学", "year": "2022追", "statement": "2NO₂ → N₂O₄ の反応エンタルピーは、正反応および逆反応の活性化エネルギーがわかれば計算で求められる。", "answer": true, "explanation": "反応エンタルピー ΔH ＝（正反応の活性化エネルギー）−（逆反応の活性化エネルギー）で求められる。"}, {"id": "r3f9356bc", "genre": "熱化学", "year": "2022追", "statement": "2NO₂ → N₂O₄ の反応エンタルピーは、NO₂ と NO の生成エンタルピーおよび反応 2NO + O₂ → 2NO₂ の反応エンタルピーがわかれば計算で求められる。", "answer": false, "explanation": "N₂O₄ に関する量が一つも含まれていないので求められない。"}, {"id": "rc7f3abd8", "genre": "熱化学", "year": "2022追", "statement": "2NO₂ → N₂O₄ の反応エンタルピーは、N₂O₄ と NO の生成エンタルピーおよび反応 2NO + O₂ → 2NO₂ の反応エンタルピーがわかれば計算で求められる。", "answer": true, "explanation": "NO の生成エンタルピーと 2NO + O₂ → 2NO₂ の反応エンタルピーから NO₂ の生成エンタルピーが求まり、N₂O₄ の生成エンタルピーと合わせてヘスの法則で計算できる。"}, {"id": "rdc791bfe", "genre": "化学基礎：酸化還元", "year": "2022追", "statement": "リン酸 H₃PO₄ のリン原子の酸化数は、+3 である。", "answer": false, "explanation": "「+3」が誤り。H を +1、O を −2 とすると、3×(+1) + x + 4×(−2) = 0 より、正しくは +5 である。"}, {"id": "r18a5e65f", "genre": "電池・電気分解", "year": "2022追", "statement": "正極に AgCl、電解液に食塩水を用いた電池では、負極を Zn から Mg にかえると起電力は大きくなる。", "answer": true, "explanation": "Mg は Zn よりイオン化傾向が大きいので、負極に用いると正極との差が大きくなり、起電力は大きくなる。"}, {"id": "r4c86daed", "genre": "電池・電気分解", "year": "2022追", "statement": "正極に AgCl、電解液に食塩水を用いた電池では、負極を Zn から Mg にかえると起電力は小さくなる。", "answer": false, "explanation": "「小さくなる」が誤り。Mg は Zn よりイオン化傾向が大きいので、正しくは起電力は大きくなる。"}, {"id": "r28d9990a", "genre": "化学基礎：原子の構造・モル", "year": "2023本", "statement": "アセトアルデヒドCH₃CHOは、すべての化学結合が単結合からなる物質である。", "answer": false, "explanation": "誤り。CH₃CHOのアルデヒド基には C＝O の二重結合が含まれる。"}, {"id": "r614ada1e", "genre": "化学基礎：原子の構造・モル", "year": "2023本", "statement": "アセチレンC₂H₂は、すべての化学結合が単結合からなる物質である。", "answer": false, "explanation": "誤り。C₂H₂の炭素原子間は C≡C の三重結合である。"}, {"id": "rb9a4c5eb", "genre": "化学基礎：原子の構造・モル", "year": "2023本", "statement": "臭素Br₂は、すべての化学結合が単結合からなる物質である。", "answer": true, "explanation": "正しい。Br₂は Br−Br の単結合（共有結合）1本だけからなる。"}, {"id": "r7f7f5988", "genre": "化学基礎：原子の構造・モル", "year": "2023本", "statement": "塩化バリウムBaCl₂は、すべての化学結合が単結合からなる物質である。", "answer": false, "explanation": "誤り。BaCl₂はBa²⁺とCl⁻がイオン結合で結びついた物質で、共有結合の単結合からなる物質ではない。"}, {"id": "r65a061f0", "genre": "溶液", "year": "2023本", "statement": "テングサを熱湯で溶出させて得た流動性のあるコロイド溶液を冷却し、流動性を失ったかたまりにしたものをゲルという。", "answer": true, "explanation": "正しい。流動性のあるコロイド溶液はゾル、それが流動性を失って固まったものがゲルである。"}, {"id": "reeebf82e", "genre": "溶液", "year": "2023本", "statement": "テングサを熱湯で溶出させて得た流動性のあるコロイド溶液を冷却し、流動性を失ったかたまりにしたものをゾルという。", "answer": false, "explanation": "誤り。流動性を失って固まったものはゲルである。ゾルは流動性のあるコロイド溶液のほう。"}, {"id": "r6e56d4e0", "genre": "溶液", "year": "2023本", "statement": "ゲルから水分を除去して乾燥させたもの（乾燥した寒天など）をキセロゲルという。", "answer": true, "explanation": "正しい。ゲルを乾燥させたものがキセロゲルで、乾燥した寒天やシリカゲルがその例である。"}, {"id": "r4e710914", "genre": "溶液", "year": "2023本", "statement": "ゲルから水分を除去して乾燥させたもの（乾燥した寒天など）をエーロゾル（エアロゾル）という。", "answer": false, "explanation": "誤り。ゲルを乾燥させたものはキセロゲルである。エーロゾルは気体中にコロイド粒子が分散したもの（煙・霧など）。"}, {"id": "rba974e2d", "genre": "固体", "year": "2023本", "statement": "硫化カルシウムCaSの結晶（塩化ナトリウム型）では、Ca²⁺とS²⁻の配位数はいずれも6である。", "answer": true, "explanation": "正しい。塩化ナトリウム型の結晶では、各イオンの前後・左右・上下に異符号のイオンが1個ずつあり、配位数は6である。"}, {"id": "r308f7e52", "genre": "固体", "year": "2023本", "statement": "硫化カルシウムCaSの結晶（塩化ナトリウム型）では、Ca²⁺とS²⁻の配位数はいずれも4である。", "answer": false, "explanation": "誤り。塩化ナトリウム型の結晶の配位数は6である。配位数4は閃亜鉛鉱（ZnS）型の結晶。"}, {"id": "rbf8a49eb", "genre": "電池・電気分解", "year": "2023本", "statement": "硝酸銀AgNO₃水溶液を白金電極で電気分解すると、水溶液の水素イオン濃度が増加する。", "answer": true, "explanation": "正しい。陽極で 2H₂O → O₂ ＋ 4H⁺ ＋ 4e⁻ の反応が起こり、H⁺が生じるので水素イオン濃度は増加する。"}, {"id": "r90597ec9", "genre": "電池・電気分解", "year": "2023本", "statement": "硝酸銀AgNO₃水溶液を白金電極で電気分解すると、陰極に銀Agが析出する。", "answer": true, "explanation": "正しい。陰極では Ag⁺ ＋ e⁻ → Ag の反応が起こり、銀が析出する。"}, {"id": "rd13b7f76", "genre": "電池・電気分解", "year": "2023本", "statement": "硝酸銀AgNO₃水溶液を白金電極で電気分解すると、陽極で水素H₂が発生する。", "answer": false, "explanation": "誤り。陽極では 2H₂O → O₂ ＋ 4H⁺ ＋ 4e⁻ の反応で酸素O₂が発生する（NO₃⁻は酸化されにくい）。"}, {"id": "rcfe8c09c", "genre": "電池・電気分解", "year": "2023本", "statement": "塩化ナトリウムNaCl水溶液を炭素電極で電気分解すると、陰極にナトリウムNaが析出する。", "answer": false, "explanation": "誤り。イオン化傾向の大きいNa⁺は還元されず、陰極では 2H₂O ＋ 2e⁻ → H₂ ＋ 2OH⁻ の反応で水素H₂が発生する。"}, {"id": "r022fe4af", "genre": "電池・電気分解", "year": "2023本", "statement": "塩化ナトリウムNaCl水溶液を炭素電極で電気分解すると、陽極で塩素Cl₂が発生する。", "answer": true, "explanation": "正しい。陽極では 2Cl⁻ → Cl₂ ＋ 2e⁻ の反応で塩素が発生する。"}, {"id": "rc6b8f6fd", "genre": "反応速度", "year": "2023本", "statement": "過酸化水素水に少量の塩化鉄(Ⅲ)FeCl₃水溶液を加えると、H₂O₂の分解反応の反応速度が大きくなる。", "answer": true, "explanation": "正しい。Fe³⁺はH₂O₂の分解反応の触媒としてはたらき、反応速度を大きくする。"}, {"id": "r86e09908", "genre": "反応速度", "year": "2023本", "statement": "肝臓などに含まれるカタラーゼを適切な条件で過酸化水素水に加えると、H₂O₂の分解反応の反応速度が大きくなる。", "answer": true, "explanation": "正しい。カタラーゼはH₂O₂の分解を促進する酵素（生体触媒）である。"}, {"id": "r3b3028ea", "genre": "反応速度", "year": "2023本", "statement": "過酸化水素の分解反応では、MnO₂の有無にかかわらず、温度を上げると反応速度が大きくなる。", "answer": true, "explanation": "正しい。温度を上げると活性化エネルギー以上のエネルギーをもつ分子の割合が増えるので、触媒の有無によらず反応速度は大きくなる。"}, {"id": "rd572a5be", "genre": "反応速度", "year": "2023本", "statement": "過酸化水素水に酸化マンガン(Ⅳ)MnO₂を加えて分解させた場合、反応の前後でマンガン原子の酸化数が変化する。", "answer": false, "explanation": "誤り。MnO₂は触媒としてはたらくだけなので、反応の前後で変化せず、マンガン原子の酸化数は＋4のままである。"}, {"id": "r59bccbc1", "genre": "化学基礎：酸塩基", "year": "2023本", "statement": "フッ化水素HFの水溶液は弱い酸性を示す。", "answer": true, "explanation": "正しい。HFは水溶液中で一部しか電離しない弱酸である（他のハロゲン化水素HCl・HBr・HIは強酸）。"}, {"id": "r77ccfcb0", "genre": "化学基礎：原子の構造・モル", "year": "2023本", "statement": "フッ化水素HFは、他のハロゲン化水素よりも沸点が高い。", "answer": true, "explanation": "正しい。HFは分子間に水素結合を形成するため、分子量が大きいHCl・HBr・HIよりも沸点が高い。"}, {"id": "r4a223d6c", "genre": "化学基礎：酸化還元", "year": "2023本", "statement": "フッ化水素HFは、ヨウ素I₂と反応してフッ素F₂を生じる。", "answer": false, "explanation": "誤り。ハロゲン単体の酸化力は F₂ ＞ Cl₂ ＞ Br₂ ＞ I₂ で、F₂の方がI₂より酸化力が強いので、I₂がF⁻を酸化してF₂を生じることはない。"}, {"id": "r740c9f7a", "genre": "化学基礎：酸化還元", "year": "2023本", "statement": "硫化水素H₂Sの水溶液に二酸化硫黄SO₂を通じて反応させると、単体の硫黄Sが生じる。", "answer": true, "explanation": "正しい。2H₂S ＋ SO₂ → 3S ＋ 2H₂O の酸化還元反応で、SO₂が酸化剤、H₂Sが還元剤としてはたらく。"}, {"id": "r352cf435", "genre": "化学基礎：酸塩基", "year": "2023本", "statement": "水酸化ナトリウムNaOHの水溶液に二酸化硫黄SO₂を通じて反応させると、亜硫酸ナトリウムNa₂SO₃が生じる。", "answer": true, "explanation": "正しい。SO₂は酸性酸化物なので塩基のNaOHと中和反応し、SO₂ ＋ 2NaOH → Na₂SO₃ ＋ H₂O となる。"}, {"id": "r92145c6b", "genre": "化学平衡", "year": "2023本", "statement": "正反応が発熱反応（ΔH＜0）である 2SO₂ ＋ O₂ ⇄ 2SO₃ の反応が平衡状態に達した後、温度一定で密閉容器内の圧力を減少させると、平衡は右に移動する。", "answer": false, "explanation": "誤り。圧力を減少させると、気体分子の数が増える向き、つまり左に平衡が移動する。"}, {"id": "r438d345e", "genre": "化学平衡", "year": "2023本", "statement": "正反応が発熱反応（ΔH＜0）である 2SO₂ ＋ O₂ ⇄ 2SO₃ の反応が平衡状態に達した後、圧力一定で密閉容器内の温度を上昇させると、平衡は左に移動する。", "answer": true, "explanation": "正しい。温度を上げると吸熱反応の向きに平衡が移動する。正反応が発熱なので、吸熱の向きは左。"}, {"id": "rc52e7760", "genre": "反応速度", "year": "2023本", "statement": "2SO₂ ＋ O₂ → 2SO₃ の反応で、SO₂の濃度を2倍にしたとき正反応の反応速度が何倍になるかは、反応式中の係数から単純に導き出すことはできない。", "answer": true, "explanation": "正しい。反応速度式の濃度の次数は実験によって決まるもので、化学反応式の係数から単純に決めることはできない。"}, {"id": "r891cc9f3", "genre": "化学平衡", "year": "2023本", "statement": "平衡状態では、正反応と逆反応の反応速度が等しくなっている。", "answer": true, "explanation": "正しい。平衡状態では正反応と逆反応が同じ速さで起こっているため、見かけ上反応が止まっているように見える。"}, {"id": "re0f0c0cd", "genre": "化学基礎：酸塩基", "year": "2023追", "statement": "1 mol/L の塩酸は、1 mol/L の酢酸水溶液よりも電気をよく通す。", "answer": true, "explanation": "HCl は強酸でほぼ完全に電離するが、酢酸は弱酸でわずかしか電離しないため、イオンの濃度が大きい塩酸の方が電気をよく通す。"}, {"id": "r7ff41cd3", "genre": "化学基礎：酸塩基", "year": "2023追", "statement": "1 mol/L のグルコース水溶液は、電気をほとんど通さない。", "answer": true, "explanation": "グルコースは水に溶けても電離しない非電解質なので、水溶液はほとんど電気を通さない。"}, {"id": "re45c10c7", "genre": "化学基礎：酸塩基", "year": "2023追", "statement": "常温・常圧で、固体の塩化ナトリウムは電気をよく通す。", "answer": false, "explanation": "イオン結晶の固体ではイオンが自由に動けないので電気を通さない（融解液や水溶液にすると通す）。"}, {"id": "rbebc7253", "genre": "状態変化", "year": "2023追", "statement": "物質が超臨界流体になると、固体、液体、気体が平衡状態で共存する。", "answer": false, "explanation": "固体・液体・気体が平衡状態で共存するのは三重点である。超臨界流体は液体とも気体とも区別できない状態。"}, {"id": "r789d446b", "genre": "状態変化", "year": "2023追", "statement": "圧力と温度がともに臨界点より高い状態にある物質は、超臨界流体である。", "answer": true, "explanation": "臨界点を超える温度・圧力では液体と気体の区別がなくなり、この状態の物質を超臨界流体という。"}, {"id": "r3a861067", "genre": "状態変化", "year": "2023追", "statement": "実在気体は、低温・高圧になるにつれて、理想気体のふるまいに近づく。", "answer": false, "explanation": "理想気体に近づくのは高温・低圧のとき。低温では分子間力の影響、高圧では分子自身の体積の影響が大きくなりずれが大きくなる。"}, {"id": "rc086c96b", "genre": "状態変化", "year": "2023追", "statement": "分子の極性は、実在気体のふるまいが理想気体のふるまいからずれる原因の一つになる。", "answer": true, "explanation": "極性分子どうしは分子間力が大きく、理想気体（分子間力なし）からのずれの原因になる。"}, {"id": "r939afff3", "genre": "状態変化", "year": "2023追", "statement": "分子自身の体積は、実在気体のふるまいが理想気体のふるまいからずれる原因の一つになる。", "answer": true, "explanation": "理想気体は分子自身の体積を0とみなすので、実在気体の分子の体積はずれの原因になる。"}, {"id": "r8ca41c86", "genre": "状態変化", "year": "2023追", "statement": "実在気体が理想気体とみなせるとき、1 mol の気体の圧力と体積の積と絶対温度の比の値は、物質の種類によらない。", "answer": true, "explanation": "理想気体では1 molについて PV/T = R（気体定数）となり、物質の種類によらず一定である。"}, {"id": "r76fb4191", "genre": "反応速度", "year": "2023追", "statement": "反応物の濃度が大きくなると、反応に関与する粒子どうしの単位時間当たりの衝突回数が増える。", "answer": true, "explanation": "濃度が大きいほど粒子が密集し、単位時間当たりの衝突回数が増えるので反応速度が大きくなる。"}, {"id": "ra9991bc2", "genre": "反応速度", "year": "2023追", "statement": "反応に関与する粒子どうしが衝突しても、活性化エネルギーを超えるエネルギーをもたないと反応が起こらない。", "answer": true, "explanation": "活性化エネルギー以上のエネルギーをもつ粒子どうしが衝突したときだけ、活性化状態を経て反応が起こる。"}, {"id": "r2207470c", "genre": "反応速度", "year": "2023追", "statement": "可逆反応で、逆反応と正反応の活性化エネルギーの差が反応エンタルピー変化の大きさと等しくなるのは、同じ活性化状態（遷移状態）を経由して反応が進行するためである。", "answer": true, "explanation": "正反応も逆反応も同じ活性化状態を通るので、両者の活性化エネルギーの差は反応物と生成物のエネルギー差（ΔHの大きさ）に等しい。"}, {"id": "rc422d0eb", "genre": "反応速度", "year": "2023追", "statement": "温度を上げると反応速度が大きくなるのは、活性化エネルギーが小さくなるためである。", "answer": false, "explanation": "温度を上げても活性化エネルギーは変わらない。活性化エネルギーを超えるエネルギーをもつ粒子の割合が増えるため速くなる（活性化エネルギーを小さくするのは触媒）。"}, {"id": "r4d87432b", "genre": "化学基礎：原子の構造・モル", "year": "2023追", "statement": "テトラアンミン亜鉛(Ⅱ)イオン中の配位結合は、亜鉛イオンの非共有電子対がアンモニアに与えられて生じる。", "answer": false, "explanation": "配位結合は、アンモニア分子の非共有電子対が亜鉛イオンに与えられて生じる（与える側と受け取る側が逆）。"}, {"id": "r4064a16e", "genre": "化学基礎：酸化還元", "year": "2023追", "statement": "Zn + 2NaOH + 2H₂O → Na₂[Zn(OH)₄] + H₂ の反応は、酸化還元反応である。", "answer": true, "explanation": "Zn の酸化数が 0→+2、H の酸化数が +1→0 と変化しているので酸化還元反応である。"}, {"id": "r3540eb7c", "genre": "化学基礎：酸化還元", "year": "2023追", "statement": "Ca(ClO)₂·2H₂O + 4HCl → CaCl₂ + 4H₂O + 2Cl₂ の反応は、酸化還元反応である。", "answer": true, "explanation": "ClO⁻ の Cl が +1→0、HCl の Cl が −1→0 と酸化数が変化しているので酸化還元反応である。"}, {"id": "r4038f31f", "genre": "化学基礎：酸化還元", "year": "2023追", "statement": "NH₄Cl + NaOH → NaCl + H₂O + NH₃ の反応は、酸化還元反応である。", "answer": false, "explanation": "どの原子の酸化数も変化していない。弱塩基の塩に強塩基を加えて弱塩基（NH₃）を遊離させる反応である。"}, {"id": "r76b7cecd", "genre": "化学基礎：酸化還元", "year": "2023追", "statement": "Cu + 2H₂SO₄ → CuSO₄ + 2H₂O + SO₂ の反応は、酸化還元反応である。", "answer": true, "explanation": "Cu の酸化数が 0→+2、S の酸化数が +6→+4 と変化しているので酸化還元反応である（熱濃硫酸の酸化作用）。"}, {"id": "r72ccc95d", "genre": "化学基礎：酸化還元", "year": "2023追", "statement": "NaCl + H₂SO₄ → NaHSO₄ + HCl の反応は、酸化還元反応である。", "answer": false, "explanation": "どの原子の酸化数も変化していない。不揮発性の酸（硫酸）で揮発性の酸（HCl）を遊離させる反応である。"}, {"id": "r3ccf98d5", "genre": "化学基礎：酸塩基", "year": "2023追", "statement": "酸化銅(Ⅱ)は、希硫酸に溶ける。", "answer": true, "explanation": "CuO は塩基性酸化物なので、酸と中和反応して塩（CuSO₄）と水を生じて溶ける。"}, {"id": "r49489859", "genre": "溶液", "year": "2023追", "statement": "架橋したポリアクリル酸ナトリウムからなる高吸水性樹脂に吸収される水の量は、純水よりも NaCl 水溶液に浸した場合の方が少ない。", "answer": true, "explanation": "NaCl 水溶液では樹脂の外側のイオン濃度も大きいので、内外のイオン濃度の差が小さくなり浸透圧が小さくなるため、吸水量が少ない。"}, {"id": "rdc335cd0", "genre": "溶液", "year": "2023追", "statement": "架橋したポリアクリル酸ナトリウムからなる高吸水性樹脂に吸収される水の量は、純水よりも NaCl 水溶液に浸した場合の方が多い。", "answer": false, "explanation": "NaCl 水溶液では樹脂内外のイオン濃度の差が小さく浸透圧が小さくなるので、吸水量は純水の場合より少ない。"}, {"id": "rdb6e0066", "genre": "溶液", "year": "2023追", "statement": "架橋したポリアクリル酸ナトリウムからなる高吸水性樹脂に吸収される水の量は、純水に浸した場合も NaCl 水溶液に浸した場合も同じである。", "answer": false, "explanation": "外液のイオン濃度によって樹脂内外の浸透圧が変わるので、吸水量は異なる（NaCl 水溶液の方が少ない）。"}, {"id": "r190bed51", "genre": "溶液", "year": "2023追", "statement": "架橋したポリアクリル酸ナトリウムからなる高吸水性樹脂を NaCl 水溶液に浸すと、架橋が切れて樹脂が溶解する。", "answer": false, "explanation": "架橋は共有結合なので NaCl 水溶液に浸しても切れず、樹脂は溶解しない（吸水量が減るだけ）。"}, {"id": "r4ab45cb9", "genre": "化学基礎：原子の構造・モル", "year": "2024本", "statement": "アンモニウムイオンNH₄⁺は、配位結合してできたイオンである。", "answer": true, "explanation": "正しい。NH₃のN原子の非共有電子対がH⁺に提供されて配位結合ができ、NH₄⁺になる。"}, {"id": "r32554580", "genre": "化学基礎：原子の構造・モル", "year": "2024本", "statement": "オキソニウムイオンH₃O⁺は、配位結合してできたイオンである。", "answer": true, "explanation": "正しい。H₂OのO原子の非共有電子対がH⁺に提供されて配位結合ができ、H₃O⁺になる。"}, {"id": "r0a4aba91", "genre": "化学基礎：原子の構造・モル", "year": "2024本", "statement": "ジアンミン銀(Ⅰ)イオン[Ag(NH₃)₂]⁺は、配位結合してできたイオンである。", "answer": true, "explanation": "正しい。NH₃分子がN原子の非共有電子対をAg⁺に提供して配位結合した錯イオンである。"}, {"id": "rb91a7772", "genre": "化学基礎：原子の構造・モル", "year": "2024本", "statement": "ギ酸イオンHCOO⁻は、配位結合してできたイオンである。", "answer": false, "explanation": "誤り。HCOO⁻はギ酸HCOOHからH⁺が電離してできたイオンで、配位結合によってできたものではない。"}, {"id": "r7e298573", "genre": "溶液", "year": "2024本", "statement": "水に溶かしたグルコースは、ろ紙を通過できる。", "answer": true, "explanation": "正しい。グルコースは水に溶けて分子として分散するので、ろ紙もセロハンの膜も通過できる。"}, {"id": "rd5ba7136", "genre": "溶液", "year": "2024本", "statement": "水に溶かしたグルコースは、セロハンの膜を通過できる。", "answer": true, "explanation": "正しい。グルコース分子はセロハンの膜の小さな穴より小さいので通過できる。"}, {"id": "rc64451a5", "genre": "溶液", "year": "2024本", "statement": "水中で分子コロイドになるトリプシンは、ろ紙を通過できる。", "answer": true, "explanation": "正しい。コロイド粒子はろ紙の穴より小さいので、ろ紙は通過できる。"}, {"id": "ree6ebc9a", "genre": "溶液", "year": "2024本", "statement": "水中で分子コロイドになるトリプシンは、セロハンの膜を通過できる。", "answer": false, "explanation": "誤り。コロイド粒子はセロハンの膜（半透膜）の穴より大きいので通過できない。"}, {"id": "re0db8834", "genre": "溶液", "year": "2024本", "statement": "水に入れてよくかき混ぜた砂は、ろ紙を通過できる。", "answer": false, "explanation": "誤り。砂は水に溶けずコロイド粒子より大きいので、ろ紙を通過できない（もちろんセロハンの膜も通過できない）。"}, {"id": "rd89ccad8", "genre": "状態変化", "year": "2024本", "statement": "水について、2×10² Paの圧力のもとでは、氷は0℃より低い温度で昇華する。", "answer": true, "explanation": "正しい。三重点（0.01℃、6.11×10² Pa）より低い圧力では液体の水は存在できず、氷は昇華曲線上の0℃より低い温度で昇華する。"}, {"id": "r6bdf03bb", "genre": "状態変化", "year": "2024本", "statement": "0℃のもとで、1.01×10⁵ Paの氷にさらに圧力を加えると、氷は融解する。", "answer": true, "explanation": "正しい。水の融解曲線は右下がり（圧力が高いほど融点が低い）なので、0℃の氷に圧力を加えると融解する。"}, {"id": "rc638b6d6", "genre": "状態変化", "year": "2024本", "statement": "0.01℃、6.11×10² Paでは、氷、水、水蒸気の三つの状態が共存できる。", "answer": true, "explanation": "正しい。この点が水の三重点で、固体・液体・気体の三態が共存できる。"}, {"id": "ree2857c0", "genre": "状態変化", "year": "2024本", "statement": "9×10⁴ Paの圧力のもとでは、水は100℃より高い温度で沸騰する。", "answer": false, "explanation": "誤り。外圧が1.01×10⁵ Paより低いと、蒸気圧が外圧に達する温度も低くなるので、沸点は100℃より低くなる。"}, {"id": "r39d52dbc", "genre": "状態変化", "year": "2024本", "statement": "1.01×10⁵ Paのもと、0℃での氷1gの体積は、同温での水1gの体積よりも小さい。", "answer": false, "explanation": "誤り。氷は水素結合ですき間の多い結晶構造をつくるため、密度が水より小さく、同じ質量なら氷の体積の方が大きい。"}, {"id": "rffbb4c39", "genre": "状態変化", "year": "2024本", "statement": "1.01×10⁵ Paのもと、断熱容器に入った4℃の水の液面をゆっくりと冷却すると、温度の低い水が下の方へ移動する。", "answer": false, "explanation": "誤り。水の密度は約4℃で最大なので、4℃より冷えた水は密度が小さくなり、下へは移動せず上に留まる。"}, {"id": "rbffb20ca", "genre": "熱化学", "year": "2024本", "statement": "硝酸アンモニウムNH₄NO₃(固)が水に溶解する変化は吸熱反応（ΔH＞0）なので、エネルギー図では NH₄NO₃aq が NH₄NO₃(固)＋aq よりも高い位置にある。", "answer": true, "explanation": "正しい。吸熱反応では生成物のエンタルピーが反応物より大きいので、生成物 NH₄NO₃aq が上になる。"}, {"id": "rddf1ba38", "genre": "熱化学", "year": "2024本", "statement": "硝酸アンモニウムNH₄NO₃(固)が水に溶解する変化は吸熱反応（ΔH＞0）なので、エネルギー図では NH₄NO₃aq が NH₄NO₃(固)＋aq よりも低い位置にある。", "answer": false, "explanation": "誤り。吸熱反応では生成物のエンタルピーが反応物より大きいので、NH₄NO₃aq の方が高い位置にある。"}, {"id": "rd5c55c6b", "genre": "化学平衡", "year": "2024本", "statement": "CO₂ ＋ H₂ ⇄ CO ＋ H₂O（すべて気体、正反応は吸熱反応）が平衡に達しているとき、圧力を一定に保ったまま温度を下げると、平衡状態のCOの物質量が増える。", "answer": false, "explanation": "誤り。温度を下げると発熱の向き（左）に平衡が移動するので、COの物質量は減る。"}, {"id": "r0030313f", "genre": "化学平衡", "year": "2024本", "statement": "CO₂ ＋ H₂ ⇄ CO ＋ H₂O（すべて気体、正反応は吸熱反応）が平衡に達しているとき、温度を一定に保ったまま圧力を上げると、平衡状態のCOの物質量が増える。", "answer": false, "explanation": "誤り。この反応は左辺・右辺とも気体2分子で分子数が変わらないので、圧力を変えても平衡は移動せず、COの物質量は変わらない。"}, {"id": "r83983fb4", "genre": "化学平衡", "year": "2024本", "statement": "CO₂ ＋ H₂ ⇄ CO ＋ H₂O（すべて気体、正反応は吸熱反応）が平衡に達しているとき、温度と圧力を一定に保ったままH₂を加えると、平衡状態のCOの物質量が増える。", "answer": true, "explanation": "正しい。反応物H₂を加えるとH₂を減らす向き（右）に平衡が移動し、COの物質量が増える。"}, {"id": "r6704b058", "genre": "化学平衡", "year": "2024本", "statement": "CO₂ ＋ H₂ ⇄ CO ＋ H₂O（すべて気体、正反応は吸熱反応）が平衡に達しているとき、温度と圧力を一定に保ったままアルゴンを加えると、平衡状態のCOの物質量が増える。", "answer": false, "explanation": "誤り。全圧一定でアルゴンを加えると各成分の分圧が下がるが、この反応は気体分子数が変わらないので平衡は移動せず、COの物質量は変わらない。"}, {"id": "rdc9e1f69", "genre": "化学平衡", "year": "2024本", "statement": "1価の弱酸HAの水溶液にNaOH水溶液を滴下するとき、NaOH水溶液の滴下量によらず、水溶液中の陽イオンの総数と陰イオンの総数は等しい。", "answer": true, "explanation": "正しい。水溶液は電気的に中性で、存在するイオン（Na⁺、H⁺、A⁻、OH⁻）はすべて1価なので、陽イオンと陰イオンの総数は等しい。"}, {"id": "r5fba2593", "genre": "化学平衡", "year": "2024本", "statement": "1価の弱酸HAの水溶液にNaOH水溶液を滴下するとき（温度一定）、NaOH水溶液の滴下量によらず、[H⁺]と[OH⁻]の積は一定である。", "answer": true, "explanation": "正しい。[H⁺][OH⁻]は水のイオン積Kwで、温度が一定なら一定である。"}, {"id": "r4cfa2efc", "genre": "化学平衡", "year": "2024本", "statement": "0.10 mol/LのHA（1価の弱酸）水溶液10.0 mLに0.10 mol/LのNaOH水溶液を滴下するとき、滴下量が10 mL未満の範囲では、HAの電離平衡の移動により[A⁻]が増加する。", "answer": true, "explanation": "正しい。加えたOH⁻がH⁺を中和して減らすため、HA ⇄ H⁺ ＋ A⁻ の平衡が右に移動して[A⁻]が増加する。"}, {"id": "r29be6f52", "genre": "化学平衡", "year": "2024本", "statement": "0.10 mol/LのHA（1価の弱酸）水溶液10.0 mLに0.10 mol/LのNaOH水溶液を滴下するとき、滴下量が10 mLより多い範囲では、中和反応により[A⁻]が減少する。", "answer": false, "explanation": "誤り。10 mLで中和は完了しており、それ以降はA⁻の物質量はほぼ変わらない。[A⁻]が減少するのは、NaOH水溶液を加えて溶液の体積が増え、薄まるためである。"}, {"id": "rc805f2cd", "genre": "化学基礎：原子の構造・モル", "year": "2024本", "statement": "アスタチンAtがF・Cl・Br・Iから推定されるとおりの性質を示すとすると、Atの単体の融点と沸点は、ともにハロゲン単体の中で最も高い。", "answer": true, "explanation": "正しい。ハロゲン単体は分子量が大きいほど分子間力（ファンデルワールス力）が強くなり、融点・沸点が高くなる。Atは最も分子量が大きい。"}, {"id": "rb43b552c", "genre": "化学基礎：酸化還元", "year": "2024本", "statement": "アスタチンAtがF・Cl・Br・Iから推定されるとおりの性質を示すとすると、臭素水をアスタチン化ナトリウムNaAt水溶液に加えても、酸化還元反応は起こらない。", "answer": false, "explanation": "誤り。ハロゲン単体の酸化力は原子番号が小さいほど強いので、Br₂はAt⁻を酸化して Br₂ ＋ 2At⁻ → 2Br⁻ ＋ At₂ の酸化還元反応が起こる。"}, {"id": "rf19fa884", "genre": "化学基礎：酸化還元", "year": "2024本", "statement": "NiS ＋ 2CuCl₂ → NiCl₂ ＋ 2CuCl ＋ S の反応で、ニッケル原子は酸化も還元もされない。", "answer": true, "explanation": "正しい。Niの酸化数はNiS中でもNiCl₂中でも＋2で変化しないので、酸化も還元もされていない。"}, {"id": "r5d0c871e", "genre": "化学基礎：酸化還元", "year": "2024本", "statement": "NiS ＋ 2CuCl₂ → NiCl₂ ＋ 2CuCl ＋ S の反応で、ニッケル原子は酸化される。", "answer": false, "explanation": "誤り。Niの酸化数は反応の前後とも＋2で変化しないので、酸化も還元もされていない。"}, {"id": "r7842bb3f", "genre": "化学基礎：酸化還元", "year": "2024本", "statement": "NiS ＋ 2CuCl₂ → NiCl₂ ＋ 2CuCl ＋ S の反応で、硫黄原子は酸化される。", "answer": true, "explanation": "正しい。Sの酸化数はNiS中の−2から単体Sの0に増加しているので、硫黄原子は酸化されている。"}, {"id": "r210cbdb6", "genre": "化学基礎：酸化還元", "year": "2024本", "statement": "NiS ＋ 2CuCl₂ → NiCl₂ ＋ 2CuCl ＋ S の反応で、硫黄原子は還元される。", "answer": false, "explanation": "誤り。Sの酸化数は−2から0に増加しているので、硫黄原子は還元ではなく酸化されている。"}, {"id": "r361cbf56", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "塩化アンモニウムの水溶液は塩基性を示す。", "answer": false, "explanation": "NH₄Clは強酸HClと弱塩基NH₃からなる塩なので、水溶液は弱い酸性を示す（塩基性ではない）。"}, {"id": "r8ca73d26", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "硫化ナトリウムの水溶液は塩基性を示す。", "answer": true, "explanation": "Na₂Sは弱酸H₂Sと強塩基NaOHからなる塩なので、S²⁻が加水分解して水溶液は塩基性を示す。"}, {"id": "r60cc77f6", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "乳酸ナトリウムの水溶液は塩基性を示す。", "answer": true, "explanation": "乳酸ナトリウムは弱酸の乳酸と強塩基NaOHからなる塩なので、水溶液は塩基性を示す。"}, {"id": "rd23bddfc", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "塩化カルシウムの水溶液は塩基性を示す。", "answer": false, "explanation": "CaCl₂は強酸HClと強塩基Ca(OH)₂からなる塩なので、水溶液は中性を示す。"}, {"id": "ra126f5ac", "genre": "化学基礎：原子の構造・モル", "year": "2024追", "statement": "14族元素の水素化合物の沸点は、CH₄、SiH₄、GeH₄、SnH₄の順に高くなる。これは、分子量が大きくなるとファンデルワールス力が強くはたらくためである。", "answer": true, "explanation": "いずれも無極性分子で、分子量が大きいほどファンデルワールス力が強くなり沸点が高くなる。"}, {"id": "rc43c394b", "genre": "化学基礎：原子の構造・モル", "year": "2024追", "statement": "HClの沸点は、分子量がほぼ同じF₂の沸点よりも高い。これは、分子の極性が小さくなると分子間力が強くはたらくためである。", "answer": false, "explanation": "理由が誤り。正しくは、分子の極性が大きくなると分子間力（静電気的な引力）が強くはたらくため。HClは極性分子、F₂は無極性分子。"}, {"id": "r9d22cd0d", "genre": "化学基礎：原子の構造・モル", "year": "2024追", "statement": "H₂Oの沸点は、H₂SやH₂Seの沸点よりも高い。これは、H₂Oでは分子間力として水素結合が強くはたらくためである。", "answer": true, "explanation": "電気陰性度の大きいOをもつH₂Oは分子間に水素結合を形成するため、分子量が大きいH₂SやH₂Seより沸点が高い。"}, {"id": "rfb677a49", "genre": "溶液", "year": "2024追", "statement": "スクロース（ショ糖）の希薄水溶液の沸点は、純水の沸点に比べて高くなる。これは、100 ℃において、この水溶液の蒸気圧が純水の蒸気圧に比べて低いためである。", "answer": true, "explanation": "不揮発性の溶質を溶かすと蒸気圧降下が起こるため、蒸気圧が外圧に達する温度が上がり沸点が上昇する。"}, {"id": "r3cdb7993", "genre": "化学基礎：原子の構造・モル", "year": "2024追", "statement": "ヘキサンは、無極性分子である。", "answer": true, "explanation": "ヘキサンはC−C結合とC−H結合だけからなる炭化水素で、無極性分子である。"}, {"id": "r3c1c62f4", "genre": "化学基礎：原子の構造・モル", "year": "2024追", "statement": "メタノールは、極性分子である。", "answer": true, "explanation": "メタノール CH₃OH は極性の大きいO−H結合をもつ極性分子である。"}, {"id": "rd40b82a1", "genre": "溶液", "year": "2024追", "statement": "室温でヘキサンは、水にほとんど溶けない。", "answer": true, "explanation": "無極性のヘキサンは極性溶媒の水とはなじまず、ほとんど溶けない。"}, {"id": "rb3ddcc00", "genre": "溶液", "year": "2024追", "statement": "室温で水とメタノールは、混合する割合によっては二層に分離する。", "answer": false, "explanation": "誤り。水とメタノールはどちらも極性分子で水素結合を形成し、任意の割合で均一に混ざり合う。"}, {"id": "rc6265ef0", "genre": "電池・電気分解", "year": "2024追", "statement": "銅の電解精錬では、純度の低い粗銅板を陽極に、純銅板を陰極として、0.3 V程度の低電圧で電気分解を行う。", "answer": true, "explanation": "陽極の粗銅が Cu → Cu²⁺ + 2e⁻ で溶け出し、陰極の純銅板上に Cu²⁺ + 2e⁻ → Cu で純銅が析出する。"}, {"id": "r8384e515", "genre": "電池・電気分解", "year": "2024追", "statement": "銅の電解精錬では、純度の低い粗銅板を陰極に、純銅板を陽極として電気分解を行う。", "answer": false, "explanation": "電極が逆。正しくは粗銅板を陽極、純銅板を陰極にする。"}, {"id": "r28601e45", "genre": "電池・電気分解", "year": "2024追", "statement": "銅の電解精錬で、粗銅に不純物として含まれる銀Agは、イオンにならず粗銅板（陽極）の下に堆積する。", "answer": true, "explanation": "AgはCuよりイオン化傾向が小さいので酸化されず、陽極泥として陽極の下に沈む。"}, {"id": "r383e2648", "genre": "電池・電気分解", "year": "2024追", "statement": "銅の電解精錬で、粗銅に不純物として含まれる亜鉛Znは、イオンにならず粗銅板（陽極）の下に堆積する。", "answer": false, "explanation": "誤り。ZnはCuよりイオン化傾向が大きいのでZn²⁺となって溶け出し、溶液中に残る（陰極には析出しない）。"}, {"id": "r9ffad416", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "NH₃を過剰の希硫酸に吸収させて、残った硫酸をNaOH水溶液で中和滴定するとき、希硫酸を入れる三角フラスコは、洗浄して純水ですすいだ後に、ぬれたまま用いてもよい。", "answer": true, "explanation": "三角フラスコ内の酸の物質量は水でうすめても変わらないので、ぬれたまま用いてよい。"}, {"id": "r6474323b", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "NH₃を過剰の希硫酸に吸収させて、残った硫酸をNaOH水溶液で中和滴定するとき、残った硫酸とNaOHが過不足なく反応した時点では、水溶液は中性となる。", "answer": false, "explanation": "誤り。溶液中に強酸と弱塩基の塩である(NH₄)₂SO₄が含まれるため、中和点の水溶液は弱い酸性になる。"}, {"id": "r833faf29", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "NH₃を過剰の希硫酸に吸収させて、残った硫酸をNaOH水溶液で中和滴定するとき、指示薬としてメチルオレンジを用いる。", "answer": true, "explanation": "中和点が(NH₄)₂SO₄により弱い酸性になるので、酸性側に変色域をもつメチルオレンジを用いる。"}, {"id": "rf944a2ad", "genre": "化学基礎：酸塩基", "year": "2024追", "statement": "NaOH水溶液で中和滴定を行うとき、ビュレットの上部にソーダ石灰管を取り付けるのは、NaOH水溶液が大気中のCO₂を吸収するのを防ぐためである。", "answer": true, "explanation": "NaOH水溶液は空気中のCO₂を吸収して濃度が変わるので、CO₂を吸収するソーダ石灰管でこれを防ぐ。"}, {"id": "r7a392728", "genre": "溶液", "year": "2024追", "statement": "セッケンは水の表面張力を低下させるはたらきをするため、セッケン水は繊維の内部に浸透することができる。", "answer": true, "explanation": "界面活性剤は水の表面張力を下げるので、水が繊維のすき間に入り込みやすくなる。"}, {"id": "r4910f9b3", "genre": "溶液", "year": "2024追", "statement": "セッケンの洗浄力は、硬水中でも低下しない。", "answer": false, "explanation": "誤り。硬水中ではセッケンがCa²⁺やMg²⁺と水に溶けにくい塩をつくるため、洗浄力が低下する。"}, {"id": "r792ead96", "genre": "溶液", "year": "2024追", "statement": "陽イオン界面活性剤は洗浄力は弱いが、頭髪用コンディショナー（リンス）などに含まれており、帯電防止効果や柔軟効果を与える。", "answer": true, "explanation": "陽イオン界面活性剤は負に帯電しやすい髪や繊維の表面に吸着し、帯電防止・柔軟効果を与える。"}, {"id": "r14577509", "genre": "溶液", "year": "2024追", "statement": "界面活性剤の乳化作用により、油分をミセル内部に取り込んだ微粒子を水中に分散させた乳濁液を得ることができ、乳化作用は食品や化粧品などに利用される。", "answer": true, "explanation": "界面活性剤は疎水基を内側にして油分を包み込んだミセルをつくり、油を水中に分散させる（乳化作用）。"}, {"id": "r95e17308", "genre": "固体", "year": "2025本", "statement": "p-ジクロロベンゼンの固体はイオン結晶である。", "answer": false, "explanation": "誤り。p-ジクロロベンゼンは分子が分子間力で集まった分子結晶である。"}, {"id": "re682cd15", "genre": "固体", "year": "2025本", "statement": "酸化マグネシウムの固体はイオン結晶である。", "answer": true, "explanation": "正しい。MgOは金属元素Mgと非金属元素Oからなり、Mg²⁺とO²⁻がイオン結合で結びついたイオン結晶である。"}, {"id": "r63396f77", "genre": "固体", "year": "2025本", "statement": "ダイヤモンドの固体はイオン結晶である。", "answer": false, "explanation": "誤り。ダイヤモンドはC原子どうしが共有結合で立体的につながった共有結合の結晶である。"}, {"id": "r51bda2b3", "genre": "固体", "year": "2025本", "statement": "アルミニウムの固体はイオン結晶である。", "answer": false, "explanation": "誤り。アルミニウムは自由電子による金属結合でできた金属結晶である。"}, {"id": "ra18f5855", "genre": "状態変化", "year": "2025本", "statement": "理想気体とみなせる互いに反応しない気体AとBを、同温・同圧で体積比1：2で混合すると、AとBの分圧の比は1：2となる。", "answer": true, "explanation": "正しい。同温・同圧での体積比は物質量比に等しく、混合気体の分圧の比は物質量比に等しいので1：2になる。"}, {"id": "r6051e7de", "genre": "状態変化", "year": "2025本", "statement": "温度一定で同じ物質量の実在気体と理想気体を比べると、十分に高圧では実在気体の体積が理想気体より大きくなる。これは、分子自身の体積が無視できなくなるためである。", "answer": true, "explanation": "正しい。高圧で気体が圧縮されると、空間に占める分子自身の体積の割合が大きくなり、実在気体の体積は理想気体より大きくなる。"}, {"id": "r32214f04", "genre": "状態変化", "year": "2025本", "statement": "圧力一定で同じ物質量の実在気体と理想気体を比べると、十分に高温では実在気体の体積は理想気体の体積に近づく。これは、分子間力の影響が小さくなるためである。", "answer": true, "explanation": "正しい。高温では分子の熱運動が激しくなり、分子間力の影響が相対的に小さくなるので理想気体に近づく。"}, {"id": "r91e855ee", "genre": "溶液", "year": "2025本", "statement": "親水コロイド溶液に多量の電解質を加えたときに沈殿が生じる現象を塩析という。", "answer": true, "explanation": "正しい。親水コロイドは水和水が多いので、多量の電解質を加えると水和水が奪われて沈殿する（塩析）。少量の電解質で疎水コロイドが沈殿するのは凝析。"}, {"id": "rd7908b97", "genre": "溶液", "year": "2025本", "statement": "分散媒が液体で分散質も液体のコロイドを懸濁液（サスペンション）という。", "answer": false, "explanation": "誤り。分散媒も分散質も液体のコロイドは乳濁液（エマルション）である。懸濁液は液体中に固体が分散したもの。"}, {"id": "r70276728", "genre": "溶液", "year": "2025本", "statement": "コロイド粒子が電荷を帯びていれば、コロイド溶液に直流電圧をかけると、コロイド粒子は自身が帯電している電荷とは反対符号の電極側に移動する。", "answer": true, "explanation": "正しい。これを電気泳動といい、正に帯電したコロイドは陰極へ、負に帯電したコロイドは陽極へ移動する。"}, {"id": "rc0022bb9", "genre": "溶液", "year": "2025本", "statement": "水に分散したコロイド粒子が不規則に運動するのは、分散媒である水分子がコロイド粒子に不規則に衝突するためである。", "answer": true, "explanation": "正しい。この不規則な運動をブラウン運動といい、熱運動する水分子が粒子に不規則に衝突して起こる。"}, {"id": "rc8c7febe", "genre": "溶液", "year": "2025本", "statement": "コロイド溶液に強い光線を当てると光の通路が明るく見えるのは、コロイド粒子が光を散乱するためである。", "answer": true, "explanation": "正しい。これをチンダル現象といい、コロイド粒子が光を散乱するために起こる。"}, {"id": "r80c15bb6", "genre": "熱化学", "year": "2025本", "statement": "科学捜査で血痕の検出に利用されるルミノール反応による光は、化学発光である。", "answer": true, "explanation": "正しい。ルミノールが酸化されるときに放出されるエネルギーが光として出る化学発光である。"}, {"id": "r8d06f04f", "genre": "熱化学", "year": "2025本", "statement": "ブレスレット型のケミカルライトの発光は、化学発光である。", "answer": true, "explanation": "正しい。ケミカルライトは中の薬品どうしを反応させ、反応のエネルギーで光る化学発光である。"}, {"id": "re64531fd", "genre": "熱化学", "year": "2025本", "statement": "ネオンサインの光は、化学発光である。", "answer": false, "explanation": "誤り。ネオンサインは管内のネオンなどの気体に放電して光らせるもので、化学反応による発光（化学発光）ではない。"}, {"id": "r317d9f55", "genre": "熱化学", "year": "2025本", "statement": "ホタルがほのかに光る発光は、化学発光である。", "answer": true, "explanation": "正しい。ホタルの発光は体内の物質が酸化される反応による発光で、化学発光の一種（生物発光）である。"}, {"id": "ra202b0b0", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "過マンガン酸カリウムKMnO₄は、塩基性水溶液中で酸化剤としてはたらくと、酸化マンガン(Ⅳ)MnO₂になる。", "answer": true, "explanation": "正しい。MnO₄⁻は中性・塩基性ではMnO₂（褐色沈殿）に、酸性ではMn²⁺に変化する。"}, {"id": "rb2740515", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "ケイ酸ナトリウムNa₂SiO₃のケイ素の酸化数は+4である。", "answer": true, "explanation": "正しい。Naが+1、Oが−2なので、2×(+1)+x+3×(−2)=0よりx=+4。"}, {"id": "re49f07ac", "genre": "化学基礎：酸塩基", "year": "2025本", "statement": "銅に濃硝酸を加えて発生する二酸化窒素NO₂を水に通じると、酸性の水溶液が生じる。", "answer": true, "explanation": "正しい。NO₂は水と反応して硝酸を生じる（3NO₂ + H₂O → 2HNO₃ + NO）ので、水溶液は酸性になる。"}, {"id": "r73a2cfe0", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "酸素に無声放電して生じるオゾンO₃の検出には、湿ったヨウ化カリウムデンプン紙を利用することができる。", "answer": true, "explanation": "正しい。O₃は強い酸化剤で、I⁻を酸化してI₂を生じさせ、I₂がデンプンと反応して青紫色になる。"}, {"id": "rc3f4b295", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "NaI水溶液に希硫酸と過酸化水素水を加えてI₂を生成させる反応（2NaI + 2H₂SO₄ + H₂O₂ → 2NaHSO₄ + 2H₂O + I₂）において、H₂O₂は酸化剤としてはたらく。", "answer": true, "explanation": "正しい。H₂O₂中のOの酸化数は−1から−2に減少しており、I⁻を酸化する酸化剤としてはたらいている。"}, {"id": "r1b65b93f", "genre": "溶液", "year": "2025本", "statement": "NaI水溶液に希硫酸と過酸化水素水を加えてI₂を生成させた反応後の混合物にヘキサンを加えると、I₂はヘキサンに抽出される。", "answer": true, "explanation": "正しい。I₂は無極性分子なので、水よりも無極性溶媒のヘキサンによく溶け、ヘキサン層に抽出される。"}, {"id": "rfaf0bef2", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "NaI水溶液に希硫酸と過酸化水素水を加えるとI₂が生成するが、H₂O₂の代わりに塩化スズ(Ⅱ)SnCl₂を用いても、I₂を生成させることができる。", "answer": false, "explanation": "誤り。SnCl₂（Sn²⁺）は還元剤なので、I⁻を酸化してI₂にすることはできない。"}, {"id": "r2b6e6a1e", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "NaI水溶液に塩素Cl₂を吹きこむと、I₂を生成させることができる。", "answer": true, "explanation": "正しい。Cl₂はI₂より酸化力が強いので、I⁻を酸化してI₂を生じる（2NaI + Cl₂ → 2NaCl + I₂）。"}, {"id": "rbb8a1560", "genre": "化学基礎：酸化還元", "year": "2025本", "statement": "オキシドバナジウムイオンVO²⁺のV原子の酸化数は+4である。", "answer": true, "explanation": "正しい。Oが−2、イオン全体の電荷が+2なので、x+(−2)=+2よりx=+4。"}, {"id": "r2e519f4e", "genre": "化学基礎：原子の構造・モル", "year": "2025追", "statement": "18族を除く第3周期までの原子では、同族の原子の大きさは、原子番号とともに大きくなる。", "answer": true, "explanation": "同族では原子番号が大きいほど電子殻の数が増えるので、原子は大きくなる。"}, {"id": "r70c4d5ea", "genre": "化学基礎：原子の構造・モル", "year": "2025追", "statement": "18族を除く第3周期までの原子では、同一周期の原子の大きさは、原子番号とともに大きくなる。", "answer": false, "explanation": "誤り。同一周期では原子番号が大きいほど原子核の正電荷が増え、電子を強く引きつけるので、原子は小さくなる。"}, {"id": "re912dcaa", "genre": "化学基礎：原子の構造・モル", "year": "2025追", "statement": "原子が陽イオンになると、もとの原子よりも大きさが小さくなる。", "answer": true, "explanation": "陽イオンになると最外殻の電子を失い（電子殻が1つ減るなど）、もとの原子より小さくなる。"}, {"id": "r745076eb", "genre": "化学基礎：原子の構造・モル", "year": "2025追", "statement": "原子が陰イオンになると、もとの原子よりも大きさが大きくなる。", "answer": true, "explanation": "陰イオンになると電子が増えて電子どうしの反発が大きくなり、原子核が電子を引きつける力が相対的に弱まるので大きくなる。"}, {"id": "r53415a29", "genre": "溶液", "year": "2025追", "statement": "ある温度で1 mol/Lに調製したショ糖水溶液の温度を変化させると、モル濃度も変化する。", "answer": true, "explanation": "温度が変わると溶液の体積が変わるので、溶液の体積を基準にするモル濃度は変化する。"}, {"id": "r111ec7c2", "genre": "溶液", "year": "2025追", "statement": "ある温度で1 mol/kgに調製した塩化ナトリウム水溶液の温度を変化させても、質量モル濃度は変化しない。", "answer": true, "explanation": "質量モル濃度は溶媒の質量を基準にするので、温度が変わっても（蒸発などがなければ）変化しない。"}, {"id": "rf6495a48", "genre": "溶液", "year": "2025追", "statement": "それぞれ1 mol/kgのショ糖水溶液および塩化ナトリウム水溶液を比べると、溶質と水の物質量の比は同じになる。", "answer": true, "explanation": "どちらも水1 kgに溶質（NaClは組成式NaClとして）1 molが溶けているので、溶質と水の物質量の比は同じ。"}, {"id": "r6d8d373b", "genre": "溶液", "year": "2025追", "statement": "ショ糖を水に溶かすと水溶液の体積は水の体積より増加する。このとき同じ温度で、1 Lの水の物質量と、1 mol/Lのショ糖水溶液1 Lに含まれる水の物質量は同じになる。", "answer": false, "explanation": "誤り。溶かすと体積が増えるので、水溶液1 Lに含まれる水は1 Lより少なく、水の物質量は1 Lの水より少ない。"}, {"id": "r01439bb4", "genre": "化学基礎：酸塩基", "year": "2025追", "statement": "HCl、HBr、HIの水溶液はいずれも強酸である。", "answer": true, "explanation": "ハロゲン化水素のうちHCl・HBr・HIの水溶液は強酸（HFの水溶液は弱酸）。"}, {"id": "r4c83282b", "genre": "化学基礎：酸化還元", "year": "2025追", "statement": "過塩素酸HClO₄のCl原子の酸化数は＋7である。", "answer": true, "explanation": "Hを＋1、Oを−2とすると、(＋1)＋x＋(−2)×4＝0より、x＝＋7。"}, {"id": "rb6a396f6", "genre": "化学基礎：酸化還元", "year": "2025追", "statement": "二酸化硫黄SO₂は水溶液中で、反応する相手の物質により酸化剤としても還元剤としてもはたらく。", "answer": true, "explanation": "SO₂は通常は還元剤としてはたらくが、H₂Sなど強い還元剤に対しては酸化剤としてはたらく。"}, {"id": "rb339c47e", "genre": "化学基礎：酸化還元", "year": "2025追", "statement": "硝酸HNO₃は、金Auと反応する。", "answer": false, "explanation": "誤り。金はイオン化傾向が非常に小さく、酸化力のある硝酸とも反応しない（溶かせるのは王水）。"}, {"id": "r5fa66ebc", "genre": "化学基礎：酸塩基", "year": "2025追", "statement": "テトラヒドロキシドアルミン酸イオン[Al(OH)₄]⁻を含む溶液に二酸化炭素CO₂の気体を通じると、溶液のpHの値が下がる。", "answer": true, "explanation": "CO₂は水に溶けて酸としてはたらき、OH⁻を中和するのでpHは下がる。"}, {"id": "rd56580e2", "genre": "化学平衡", "year": "2025追", "statement": "[Al(OH)₄]⁻を含む溶液にCO₂を通じると水酸化アルミニウムAl(OH)₃の沈殿が生じるのは、[Al(OH)₄]⁻ ⇄ Al(OH)₃ ＋ OH⁻ の化学平衡が右側に移動するためである。", "answer": true, "explanation": "CO₂がOH⁻を消費するので、ルシャトリエの原理によりOH⁻を生じる右向きに平衡が移動し、Al(OH)₃が沈殿する。"}, {"id": "r2e892d3b", "genre": "化学基礎：原子の構造・モル", "year": "2025追", "statement": "Al(OH)₃を加熱してAl₂O₃を得る反応では、2 molのAl(OH)₃から1 molのAl₂O₃と2 molの水H₂Oが生成する。", "answer": false, "explanation": "誤り。2Al(OH)₃ → Al₂O₃ ＋ 3H₂O なので、生成する水は3 mol。"}, {"id": "rd871d53e", "genre": "電池・電気分解", "year": "2025追", "statement": "Al₂O₃を氷晶石Na₃AlF₆とともに融解させて溶融塩電解するのは、純物質のAl₂O₃が融解する温度よりも、Na₃AlF₆とAl₂O₃の混合物が融解する温度の方が低いという性質を利用している。", "answer": true, "explanation": "Al₂O₃の融点は非常に高い（約2000 ℃）が、氷晶石との混合物は約1000 ℃で融解するので、低い温度で電解できる。"}];
const RUSH_GENRES = ["化学基礎：原子の構造・モル", "化学基礎：酸塩基", "化学基礎：酸化還元", "状態変化", "固体", "溶液", "電池・電気分解", "熱化学", "反応速度", "化学平衡"];
